import hashlib
import time
import threading
from enum import Enum
from collections import defaultdict
from typing import Optional, Dict, Any, Tuple


class CircuitState(Enum):
    CLOSED = "closed"
    OPEN = "open"
    HALF_OPEN = "half_open"


class CircuitBreaker:
    def __init__(self, failure_threshold=5, recovery_timeout=30):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.failure_count = 0
        self.last_failure_time = 0
        self.state = CircuitState.CLOSED
        self._lock = threading.Lock()

    def record_failure(self):
        with self._lock:
            self.failure_count += 1
            self.last_failure_time = time.time()
            if self.failure_count >= self.failure_threshold:
                self.state = CircuitState.OPEN

    def record_success(self):
        with self._lock:
            self.failure_count = 0
            self.state = CircuitState.CLOSED

    def can_execute(self) -> bool:
        with self._lock:
            if self.state == CircuitState.CLOSED:
                return True
            if self.state == CircuitState.OPEN:
                if time.time() - self.last_failure_time > self.recovery_timeout:
                    self.state = CircuitState.HALF_OPEN
                    return True
                return False
            return True  # HALF_OPEN allows one request


class CacheNode:
    def __init__(self, host: str, port: int):
        self.host = host
        self.port = port
        self.data: Dict[str, Any] = {}
        self.circuit_breaker = CircuitBreaker()

    def get(self, key: str) -> Optional[Any]:
        return self.data.get(key)

    def set(self, key: str, value: Any):
        self.data[key] = value

    def delete(self, key: str):
        self.data.pop(key, None)


class DistributedCacheClient:
    """Distributed cache client with consistent hashing and circuit breaker."""

    def __init__(self, nodes: list, virtual_nodes: int = 150):
        self.nodes: Dict[str, CacheNode] = {}
        self.ring: list = []
        self.virtual_nodes = virtual_nodes
        self._ring_lock = threading.RLock()
        for host, port in nodes:
            self.add_node(host, port)

    def _hash(self, key: str) -> int:
        return int(hashlib.md5(key.encode()).hexdigest(), 16)

    def add_node(self, host: str, port: int):
        node = CacheNode(host, port)
        node_id = f"{host}:{port}"
        self.nodes[node_id] = node
        with self._ring_lock:
            for i in range(self.virtual_nodes):
                vnode_key = f"{node_id}#v{i}"
                h = self._hash(vnode_key)
                self.ring.append((h, node_id))
            self.ring.sort(key=lambda x: x[0])

    def _get_node(self, key: str) -> Optional[CacheNode]:
        if not self.ring:
            return None
        h = self._hash(key)
        with self._ring_lock:
            for hash_val, node_id in self.ring:
                if hash_val >= h:
                    node = self.nodes[node_id]
                    if node.circuit_breaker.can_execute():
                        return node
                    continue
            # Wrap around
            for hash_val, node_id in self.ring:
                node = self.nodes[node_id]
                if node.circuit_breaker.can_execute():
                    return node
        return None

    def _build_scoped_key(self, tenant_id: str, key: str) -> str:
        """Build a tenant-scoped cache key for isolation."""
        return f"{tenant_id}:{key}"

    def _validate_access(self, tenant_id: str, scoped_key: str) -> bool:
        """Validate that the tenant owns the scoped key."""
        prefix = scoped_key.split(":", 1)[0]
        return prefix == tenant_id

    def get(self, tenant_id: str, key: str, fallback_tenant: Optional[str] = None) -> Optional[Any]:
        """Get a value from cache with tenant isolation.

        If the primary lookup fails due to circuit breaker, attempts
        fallback lookup using degraded mode.
        """
        scoped_key = self._build_scoped_key(tenant_id, key)

        if not self._validate_access(tenant_id, scoped_key):
            return None

        node = self._get_node(scoped_key)
        if node is None:
            return self._degraded_get(tenant_id, key, fallback_tenant)

        try:
            result = node.get(scoped_key)
            node.circuit_breaker.record_success()
            if result is not None:
                return result
            # Cache miss - try degraded mode
            return self._degraded_get(tenant_id, key, fallback_tenant)
        except Exception:
            node.circuit_breaker.record_failure()
            return self._degraded_get(tenant_id, key, fallback_tenant)

    def _degraded_get(self, tenant_id: str, key: str, fallback_tenant: Optional[str] = None) -> Optional[Any]:
        """Degraded mode: scan all available nodes for the key.

        In degraded mode, we attempt to find the data on any available node
        to maintain availability during partial failures.
        """
        # Use fallback_tenant for shared/public cache entries
        lookup_tenant = fallback_tenant if fallback_tenant else tenant_id
        scoped_key = self._build_scoped_key(lookup_tenant, key)

        for node_id, node in self.nodes.items():
            if node.circuit_breaker.can_execute():
                try:
                    result = node.get(scoped_key)
                    if result is not None:
                        node.circuit_breaker.record_success()
                        return result
                except Exception:
                    node.circuit_breaker.record_failure()
        return None

    def set(self, tenant_id: str, key: str, value: Any) -> bool:
        """Set a value in cache with tenant isolation."""
        scoped_key = self._build_scoped_key(tenant_id, key)

        if not self._validate_access(tenant_id, scoped_key):
            return False

        node = self._get_node(scoped_key)
        if node is None:
            return False

        try:
            node.set(scoped_key, value)
            node.circuit_breaker.record_success()
            return True
        except Exception:
            node.circuit_breaker.record_failure()
            return False

    def delete(self, tenant_id: str, key: str) -> bool:
        """Delete a value from cache."""
        scoped_key = self._build_scoped_key(tenant_id, key)

        if not self._validate_access(tenant_id, scoped_key):
            return False

        node = self._get_node(scoped_key)
        if node is None:
            return False

        try:
            node.delete(scoped_key)
            node.circuit_breaker.record_success()
            return True
        except Exception:
            node.circuit_breaker.record_failure()
            return False


# Example usage showing multi-tenant cache access
def handle_request(cache: DistributedCacheClient, requesting_tenant: str, resource_key: str):
    """Handle a cache request from a tenant."""
    result = cache.get(requesting_tenant, resource_key)
    return result
